+static struct sparx5_rr_nexthop_group *
+sparx5_rr_nexthop_group_create(struct sparx5 *sparx5,
+			       struct sparx5_rr_fib_entry *fib_entry)
+{
+	struct sparx5_rr_nexthop_group *nh_grp;
+	int err;
