+	nh_grp = kzalloc_obj(*nh_grp);
+	if (!nh_grp)
+		return ERR_PTR(-ENOMEM);
+
+	err = sparx5_rr_nexthop_group_info_init(sparx5, nh_grp, &fib_entry->fi);
+	if (err)
+		goto err_group_info_init;
+
+	return nh_grp;
+
+err_group_info_init:
+	kfree(nh_grp);
+	return ERR_PTR(err);
+}
