+	default:
+		WARN_ON_ONCE(1); /* BUG */
+		break;
+	}
+
+	/* Release fib6_info holds for workqueue. */
+	sparx5_rr_fib_info_put(fi);
+	mutex_unlock(&sparx5->router->lock);
